+import { minorUnitFactor } from "./money";
+
+interface ExportInvoice {
+  invoiceNumber: string;
+  company: { name: string };
+  currencyCode: string;
+  issueDate: Date | string;
+  dueDate: Date | string | null;
+  totalMinor: number | bigint;
+  paidMinor: number | bigint;
+  status: string;
+}
+
+function amount(minor: number | bigint, currency: string) {
+  const value = BigInt(minor);
+  if (minorUnitFactor(currency) === 1) return value.toString();
+  const absolute = value < 0n ? -value : value;
+  return `${value < 0n ? "-" : ""}${absolute / 100n}.${String(absolute % 100n).padStart(2, "0")}`;
+}
+
+function field(value: string) {
+  return /[",\r\n]/.test(value) ? `"${value.replace(/"/g, '""')}"` : value;
+}
+
+const date = (value: Date | string) => new Date(value).toISOString().slice(0, 10);
+
+/** Accountant export revision 2. Uses precisely the current list and its order. */
+export function invoiceCsv(invoices: readonly ExportInvoice[]) {
+  const rows = ["invoice_number,company,currency,issue_date,due_date,total,paid,balance_due,status"];
+  for (const invoice of invoices) {
+    const currency = invoice.currencyCode.toUpperCase();
+    const remaining = BigInt(invoice.totalMinor) - BigInt(invoice.paidMinor);
